	lines = append(lines, "  --profile <name>                 use an isolated saved profile (or set "+profileEnv+")")
	for _, flag := range authScalarFlags {
		lines = append(lines, "  "+bin+" login --"+flag+" <value>          store the credential (or set "+authCredentialEnvs[flag]+" in the environment)")
	}
	lines = append(lines, "  "+bin+" login                        approve in the browser: a key is minted for you (add --no-browser to print the link instead of opening it)")
	lines = append(lines, "  "+bin+" login --with-token             read the credential from stdin (CI)")
	lines = append(lines, "", "Precedence per scheme: flags > env vars > stored credentials.")
	return strings.Join(lines, "\n")
