// runLogoutCommand removes the stored credentials. A key this CLI
// minted for itself (browser approval) or an OAuth session with a
// revocation endpoint is revoked on the way out, so logging out ends
// the credential and not just the file; a pasted or CI key belongs to
// someone else and is left alone.
func runLogoutCommand(args []string, stdout, stderr io.Writer) int {
	if len(args) != 1 && !(len(args) == 2 && args[1] == "--local") {
		fmt.Fprintln(stderr, "usage: "+bin+" logout [--local]")
		return 2
	}
	if len(args) == 2 && args[1] == "--local" {
		unlock, err := lockStoredAuth()
		if err != nil {
			fmt.Fprintln(stderr, err)
			return 1
		}
		existed := true
		if err := os.Remove(authPath()); os.IsNotExist(err) {
			existed = false
		} else if err != nil {
			unlock()
			fmt.Fprintln(stderr, err)
			return 1
		}
		unlock()
		report := map[string]any{"ok": true, "removed": nil, "revoked": false, "revocation_skipped": true}
		if existed {
			report["removed"] = authPath()
		}
		b, _ := json.Marshal(report)
		fmt.Fprintln(stdout, string(b))
		return 0
	}
	unlock, err := lockStoredAuth()
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	stored := readStoredAuth()
	existed := true
	if err := os.Remove(authPath()); os.IsNotExist(err) {
		existed = false
	} else if err != nil {
		unlock()
		fmt.Fprintln(stderr, err)
		return 1
	}
	unlock()
	attempted, revoked := false, false
	if stored.Minted != nil && stored.Minted.Via == "browser" && stored.Minted.RevocationURL != "" && len(authScalarFlags) > 0 {
		if key := stored.Scalars[authCredentialKeys[authScalarFlags[0]]]; key != "" {
			attempted, revoked = true, revokeBearer(stored.Minted.RevocationURL, key)
		}
	}
	if stored.OAuth != nil && stored.OAuth.RevocationURL != "" && (stored.OAuth.RefreshToken != "" || stored.OAuth.AccessToken != "") {
		attempted, revoked = true, revokeOAuthToken(stored.OAuth)
	}
	report := map[string]any{"ok": true, "removed": nil}
	if existed {
		report["removed"] = authPath()
	}
	if attempted {
		report["revoked"] = revoked
		if stored.Minted != nil && stored.Minted.Via == "browser" {
			report["key_name"] = stored.Minted.KeyName
		}
	}
	b, _ := json.Marshal(report)
	fmt.Fprintln(stdout, string(b))
	return 0
}

// whoamiCall invokes the configured identity operation with the
// resolved credentials. It returns the API's identity payload on
// success, or the classified issue code and a one-line message.
func whoamiCall(ctx context.Context, args, surfaceArgs []string) (any, string, string) {
	op := findOp(whoamiResource, whoamiCommand)
	if op == nil {
		return nil, "CALL_FAILED", "the configured identity operation is not available in this package"
	}
	code, message, _ := identitySurfaceError(op, surfaceArgs)
	if code != "" {
		return nil, code, message
	}
	opts, optErr := authOptions(ctx, args, op, surfaceArgs)
	if optErr != nil {
		return nil, "AUTH_INVALID", optErr.Error()
	}
	opts = append(opts, identityTransportOptions()...)
	client, err := sdk.New(opts...)
	if err != nil {
		return nil, failureCode(err), "unable to initialize the client"
	}
	result, err := invoke(client, ctx, *op, nil, map[string]opFlagValue{}, nil)
	if err != nil {
		if ctx.Err() != nil {
			return nil, "CALL_FAILED", "cancelled"
		}
		code := failureCode(err)
		if code == "AUTH_INVALID" && !credentialPresent(args) {
			code = "NO_AUTH"
		}
		return nil, code, "the API rejected the credential for its identity read"
	}
	return result, "", ""
}

// runWhoamiCommand prints the caller's identity. With an identity
// operation, it calls that operation with the resolved credentials and
// prints the payload; without one, it reports which credential the CLI
// would use.
func runWhoamiCommand(ctx context.Context, args, surfaceArgs []string, stdout, stderr io.Writer) int {
	if !whoamiEnabled {
		source := authCredentialSource(ctx, args)
		report := map[string]any{"authenticated": source != "none", "source": source, "credentials": nil}
		if _, err := os.Stat(authPath()); err == nil {
			report["credentials"] = authPath()
		}
		problem := storedCredentialProblem(ctx, args)
		if problem != nil {
			report["authenticated"] = false
			report["issues"] = []map[string]string{{"code": "AUTH_INVALID", "message": problem.Error()}}
			report["next_steps"] = storedCredentialNextSteps()
		}
		b, _ := json.MarshalIndent(redactReport(report, args), "", "  ")
		fmt.Fprintln(stdout, string(b))
		if source == "none" || problem != nil {
			return 1
		}
		return 0
	}
	op := findOp(whoamiResource, whoamiCommand)
	if op == nil {
		return writeFailure(args, stdout, stderr, "CALL_FAILED", "the configured identity operation is not available in this package", nil, nil, 1)
	}
	code, message, next := identitySurfaceError(op, surfaceArgs)
	if code != "" {
		return writeFailure(args, stdout, stderr, code, message, nil, next, 2)
	}
	positionals, values, data, help, parseErr := parseOpArgs(*op, args[1:])
	if help {
		fmt.Fprint(stdout, op.Help)
		return 0
	}
	if parseErr != nil {
		code := "INVALID_USAGE"
		if strings.Contains(parseErr.Error(), "unknown flag") {
			code = "UNKNOWN_FLAG"
		}
		return writeFailure(args, stdout, stderr, code, parseErr.Error(), op.Help, nil, 2)
	}
	if len(positionals) != 0 {
		return writeFailure(args, stdout, stderr, "MISSING_ARGUMENT", fmt.Sprintf("expected 0 positional argument(s), got %d", len(positionals)), op.Help, nil, 2)
	}
	opts, optErr := authOptions(ctx, args, op, surfaceArgs)
	if optErr != nil {
		return writeFailure(args, stdout, stderr, "AUTH_INVALID", optErr.Error(), nil, []string{"run 'typeship login' to sign in again"}, 1)
	}
	opts = append(opts, identityTransportOptions()...)
	client, err := sdk.New(opts...)
	if err != nil {
		return writeFailure(args, stdout, stderr, failureCode(err), "unable to initialize the client", errorDetail(err, args), nil, 1)
	}
	result, err := invoke(client, ctx, *op, positionals, values, data)
	if err != nil {
		if ctx.Err() != nil {
			return 130
		}
		return writeRequestFailure(args, stdout, stderr, err)
	}
	out, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return writeFailure(args, stdout, stderr, "CALL_FAILED", "could not encode response", err.Error(), nil, 1)
	}
	fmt.Fprintln(stdout, string(out))
	return 0
}

// runAuthCheckCommand reports the credential the CLI would send as
// JSON. --live also verifies it against the API's identity endpoint:
// without one (or without the flag) the check stays offline.
func runAuthCheckCommand(ctx context.Context, args, surfaceArgs []string, stdout, stderr io.Writer) int {
	if len(args) < 2 || args[1] != "check" {
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", "usage: "+bin+" auth check [--live]", nil, nil, 2)
	}
	if _, _, err := invocationNamedCredentialSources(ctx, args); err != nil {
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", err.Error(), nil, nil, 2)
	}
	source := authCredentialSource(ctx, args)
	authenticated := source != "none"
	base, environment, authCfg, resolveErr := resolveAuthContext(args, readConfig())
	report := map[string]any{}
	report["status"] = "ok"
	report["authenticated"] = authenticated
	report["source"] = source
	report["profile"] = activeProfile.Name
	report["profile_source"] = activeProfile.Source
	report["base_url"] = safeEffectiveBaseURL(base)
	report["environment"] = environment
	report["binding"] = effectiveBindingReport(ctx, args, source, base, environment, authCfg)
	report["credentials_path"] = nil
	report["next_steps"] = []string{}
	if resolveErr != nil {
		authenticated = false
		report["status"] = "action_required"
		report["authenticated"] = false
		report["issues"] = []map[string]string{{"code": "AUTH_INVALID", "message": resolveErr.Error()}}
		report["next_steps"] = []string{"select a configured environment or API base URL, then run '" + bin + " auth check'"}
	}
	if _, err := os.Stat(authPath()); err == nil {
		report["credentials_path"] = authPath()
	}
	if resolveErr == nil && !authenticated {
		report["status"] = "action_required"
		report["next_steps"] = []string{"set the auth environment variable, pass an auth flag, or run '" + bin + " login'"}
	}
	// Saved credentials that no request would send (unbound, or bound to
	// another destination) are not a working login; report that before
	// any live call, which would refuse them the same way.
	if problem := storedCredentialProblem(ctx, args); resolveErr == nil && problem != nil {
		authenticated = false
		report["status"] = "action_required"
		report["authenticated"] = false
		report["issues"] = []map[string]string{{"code": "AUTH_INVALID", "message": problem.Error()}}
		report["next_steps"] = storedCredentialNextSteps()
	}
	if authenticated && hasFlag(args, "--live") && !whoamiEnabled {
		report["live"] = map[string]any{"ok": nil, "message": "this API declares no identity operation, so the credential was checked locally only"}
	}
	if authenticated && hasFlag(args, "--live") && whoamiEnabled {
		identity, code, message := whoamiCall(ctx, args, surfaceArgs)
		if code == "" {
			if err := validateLiveIdentity(ctx, identity, args); err != nil {
				report["status"] = "action_required"
				report["live"] = map[string]any{"ok": false, "code": "AUTH_INVALID", "message": err.Error()}
				report["next_steps"] = []string{"run '" + bin + " login' with the intended account and organization, then retry '" + bin + " auth check --live'"}
			} else {
				report["identity"] = identity
			}
		} else {
			report["status"] = "action_required"
			report["live"] = map[string]any{"ok": false, "code": code, "message": message}
			report["next_steps"] = []string{"run '" + bin + " login' to refresh credentials, then retry '" + bin + " auth check --live'"}
		}
	}
	b, _ := json.MarshalIndent(redactReport(report, args), "", "  ")
	fmt.Fprintln(stdout, string(b))
	if report["status"] == "action_required" {
		return 1
	}
	return 0
}

// runConfigCommand reads, prints, updates, or clears persistent CLI
// configuration and returns a success, runtime-error, or usage status.
func runConfigCommand(args []string, stdout, stderr io.Writer) int {
	if len(args) < 2 || args[1] == "path" {
		fmt.Fprintln(stdout, configPath())
		return 0
	}
	if args[1] == "list" {
		c := readConfig()
		b, _ := json.Marshal(c)
		fmt.Fprintln(stdout, string(b))
		return 0
	}
	if args[1] == "profile" {
		if len(args) == 3 && args[2] == "list" {
			names := map[string]bool{"default": true}
			entries, err := os.ReadDir(filepath.Join(configRootPath(), "profiles"))
			if err != nil && !os.IsNotExist(err) {
				fmt.Fprintln(stderr, "cannot list profiles")
				return 1
			}
			for _, entry := range entries {
				if entry.IsDir() && entry.Type()&os.ModeSymlink == 0 && validProfileName(entry.Name()) {
					names[entry.Name()] = true
				}
			}
			profiles := []map[string]any{}
			for name := range names {
				directory, err := profileDirectory(name)
				if err != nil {
					continue
				}
				_, plainErr := os.Stat(filepath.Join(directory, "credentials.json"))
				_, encryptedErr := os.Stat(filepath.Join(directory, "credentials.enc"))
				profile := map[string]any{}
				profile["name"] = name
				profile["selected"] = name == activeProfile.Name
				profile["has_credentials"] = plainErr == nil || encryptedErr == nil
				profiles = append(profiles, profile)
			}
			sort.Slice(profiles, func(i, j int) bool { return profiles[i]["name"].(string) < profiles[j]["name"].(string) })
			_ = json.NewEncoder(stdout).Encode(map[string]any{"profiles": profiles, "selected": activeProfile.Name})
			return 0
		}
		if len(args) == 4 && args[2] == "use" {
			directory, err := profileDirectory(args[3])
			if err != nil {
				fmt.Fprintln(stderr, err)
				return 2
			}
			if err := os.MkdirAll(directory, 0700); err != nil {
				fmt.Fprintln(stderr, "cannot create the selected profile")
				return 1
			}
			if err := writeSelectedProfile(args[3]); err != nil {
				fmt.Fprintln(stderr, "cannot select the profile")
				return 1
			}
			_ = json.NewEncoder(stdout).Encode(map[string]any{"ok": true, "selected": args[3]})
			return 0
		}
		fmt.Fprintln(stderr, "usage: config profile list|use <name>")
		return 2
	}
	if args[1] == "get" && len(args) >= 3 {
		c := readConfig()
		switch args[2] {
		case "base-url":
			fmt.Fprintln(stdout, c.BaseURL)
		case "environment":
			fmt.Fprintln(stdout, c.Environment)
		case "docs-url":
			fmt.Fprintln(stdout, c.DocsURL)
		default:
			fmt.Fprintln(stderr, "unknown config key")
			return 2
		}
		return 0
	}
	if args[1] == "set" && len(args) >= 4 {
		c := readConfig()
		switch args[2] {
		case "base-url":
			c.BaseURL = args[3]
		case "environment":
			if _, ok := environments[args[3]]; !ok {
				fmt.Fprintln(stderr, "unknown environment")
				return 2
			}
			c.Environment = args[3]
			c.BaseURL = ""
		case "docs-url":
			c.DocsURL = args[3]
		default:
			fmt.Fprintln(stderr, "unknown config key")
			return 2
		}
		if err := writeConfig(c); err != nil {
			fmt.Fprintln(stderr, err)
			return 1
		}
		fmt.Fprintln(stdout, `{"ok":true}`)
		return 0
	}
	if args[1] == "unset" && len(args) >= 3 {
		c := readConfig()
		switch args[2] {
		case "base-url":
			c.BaseURL = ""
		case "environment":
			c.Environment = ""
		case "docs-url":
			c.DocsURL = ""
		default:
			fmt.Fprintln(stderr, "unknown config key")
			return 2
		}
		if err := writeConfig(c); err != nil {
			fmt.Fprintln(stderr, err)
			return 1
		}
		fmt.Fprintln(stdout, `{"ok":true}`)
		return 0
	}
	fmt.Fprintln(stderr, "usage: config list|path|get|set|unset <base-url|environment|docs-url>")
	return 2
}

func safeEffectiveBaseURL(raw string) any {
	if raw == "" {
		return nil
	}
	parsed, err := url.Parse(raw)
	if err != nil || parsed.Scheme == "" || parsed.Host == "" {
		return "[invalid URL]"
	}
	parsed.User = nil
	parsed.RawQuery = ""
	parsed.Fragment = ""
	return normalizeURL(parsed.String())
}

func effectiveBindingReport(ctx context.Context, args []string, source, base, environment string, cfg authEnvironmentConfig) map[string]any {
	if source != "stored" && source != "legacy" {
		return map[string]any{"status": "not_applicable"}
	}
	stored := requestStoredAuth(ctx, args)
	result := map[string]any{"status": "unbound"}
	if stored.Destination == nil {
		return result
	}
	result["api_base_url"] = safeEffectiveBaseURL(stored.Destination.APIBaseURL)
	result["environment"] = stored.Destination.Environment
	result["profile"] = stored.Destination.Profile
	switch {
	case stored.Destination.APIBaseURL == "":
		result["status"] = "unbound"
	case !sameURL(stored.Destination.APIBaseURL, base) || stored.Destination.Environment != environment || stored.Destination.Profile != activeProfile.Name:
		result["status"] = "mismatch"
	default:
		result["status"] = "bound"
		if err := validateStoredForRequest(stored, base, environment, cfg); err != nil {
			result["status"] = "invalid"
		}
	}
	return result
}
